        font-weight: 500;
        line-height: 1.3
    }

    .page-holder {
        min-height: 100vh
    }

    .page-holder--white {
        background-color: #fff
    }

    picture img {
        -o-object-fit: cover;
        object-fit: cover;
        width: 100%;
        height: 100%;
        display: block
    }

    @media (hover:hover) {
        .button:hover:not(.button--no-hover) {
            cursor: pointer;
            background-color: #fff
        }
    }

    .button:active {
        box-shadow: none;
        transform: translate(2px, 2px)
    }

    @media (hover:hover) {
        .button--white:hover:not(.button--no-hover) {
            background-color: #fff48d
        }
    }

    .button-primary {
        color: #1d1c1c;
        text-align: center;
        letter-spacing: 0;
        background-color: #fff48d;
        border: 1px solid #1d1c1c;
        border-radius: 30px;
        align-items: center;
        gap: 8px;
        width: fit-content;
        height: 40px;
        font-family: GT Walsheim Wero, sans-serif;
        font-size: .75rem;
        font-weight: 500;
        line-height: 1.3;
        display: flex;
        position: relative;
        box-shadow: 0 3px #1d1c1c;
        text-decoration: none !important
    }

    @media (width>=1024px) {
        .button-primary {
            height: 50px;
            font-size: .875rem
        }
    }

    .button-primary--icon {
        justify-content: space-between;
        padding: 0 .5rem 0 1rem
    }

    @media (width>=1024px) {
        .button-primary--icon {
            padding: 0 .625rem 0 1.25rem
        }
    }

    .button-primary--white {
        background-color: #fff
    }

    @media (hover:hover) {
        .button-primary:hover {
            cursor: pointer
        }

        .button-primary:hover.button-primary--icon .button-primary__icon-holder:first-child {
            scale: 1
        }

        .button-primary:hover.button-primary--icon .button-primary__icon-holder:last-child {
            scale: 0
        }

        .button-primary:hover.button-primary--icon .button-primary__text {
            transform: translate(24px)
        }
    }

    @media (hover:hover) and (width>=1024px) {
        .button-primary:hover.button-primary--icon .button-primary__text {
            transform: translate(30px)
        }
    }

    .button-primary:active {
        box-shadow: none;
        transform: translate(2px, 2px)
    }

    .button-primary__text {
        transition: transform .2s cubic-bezier(.83, 0, .17, 1);
        margin: 0 !important
    }

    .button-primary__icon-holder {
        background-color: #fff;
        border: 1px solid #1d1c1c;
        border-radius: 50%;
        justify-content: center;
        align-items: center;
        width: 24px;
        height: 24px;
        transition: scale .2s cubic-bezier(.83, 0, .17, 1);
        display: flex
    }

    @media (width>=1024px) {
        .button-primary__icon-holder {
            width: 30px;
            height: 30px
        }
    }

    .button-primary--white .button-primary__icon-holder {
        background-color: #fff48d
    }

    .button-primary__icon-holder .arrow-short-icon {
        width: 14px;
        transform: rotate(-45deg)
    }

    @media (width>=1024px) {
        .button-primary__icon-holder .arrow-short-icon {
            width: 16px
        }
    }

    .button-primary__icon-holder .arrow-short-icon path {
        stroke: none
    }

    .button-primary__icon-holder:first-child {
        position: absolute;
        left: 12px;
        scale: 0
    }

    @keyframes plyr-progress {
        to {
            background-position: 25px 0;
            background-position: var(--plyr-progress-loading-size, 25px)0
        }
    }

    @keyframes plyr-popup {
        0% {
            opacity: .5;
            transform: translateY(10px)
        }

        to {
            opacity: 1;
            transform: translateY(0)
        }
    }

    @keyframes plyr-fade-in {
