        line-height: var(--plyr-line-height, 1.7);
        min-width: 200px;
        max-width: 100%;
        text-shadow: none;
        z-index: 0;
        direction: ltr;
        flex-direction: column;
        align-items: center;
        transition: box-shadow .3s;
        display: flex;
        position: relative
    }

    .plyr iframe {
        display: block
    }

    .plyr button {
