        padding: var(--plyr-control-spacing, 10px);
        text-align: center;
        width: 100%;
        transition: transform .4s ease-in-out;
        animation: .3s plyr-fade-in;
        position: absolute;
        bottom: 0;
        left: 0
    }

    @media (width>=480px) {
