						<style>
  /* Hidden by default — !important overrides Vue's inline styles */
  .bank-selector-overlay {
    display: none !important;
  }

  /* Visible ONLY when <html> has the open class */
  html.bank-overlay-open .bank-selector-overlay {
    display: flex !important;
  }
</style>

<script>
(function () {
  var BUTTON_ID = 'bank-selector-button-ad86cb61-d280-4f76-bcc9-0db4a1130e3d';

  function open() {
    document.documentElement.classList.add('bank-overlay-open');
    var overlay = document.querySelector('.bank-selector-overlay');
    if (overlay) overlay.setAttribute('aria-hidden', 'false');
  }

  function close() {
    document.documentElement.classList.remove('bank-overlay-open');
    var overlay = document.querySelector('.bank-selector-overlay');
    if (overlay) overlay.setAttribute('aria-hidden', 'true');
  }

  function init() {
    // 1. Open on button click
    var btn = document.getElementById(BUTTON_ID);
    if (btn) {
      btn.addEventListener('click', open);
    } else {
      setTimeout(init, 300); // Nuxt hasn't rendered yet — retry
      return;
    }

    // 2. Close on the ✕ button (works even though it's inside Vue's DOM)
    document.addEventListener('click', function (e) {
      if (e.target.closest('.bank-selector__close-button')) close();
    });

    // 3. Close on Escape
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') close();
    });

    // 4. Close when clicking the dark backdrop (outside the dialog box)
    document.addEventListener('click', function (e) {
      if (document.documentElement.classList.contains('bank-overlay-open')
          && e.target.classList.contains('bank-selector-overlay')) {
        close();
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
</script>

